/* PDF marking and measured values. PDF originals and records are kept together in IndexedDB. */
const MEASURE_KINDS={
 '鉄骨':['アンカーボルト径','ボルトピッチ X','ボルトピッチ Y','突出長','天端レベル'],
 '鉄筋':['鉄筋径','本数','ピッチ','かぶり厚さ','定着長','継手長'],
 '金物':['金物寸法','取付位置 X','取付位置 Y','取付高さ','埋込み長'],
 '配管':['管径','高さ・レベル','位置ずれ X','位置ずれ Y','勾配']
};
let measureReady=false,measureFolderBusy=false;const collapsedMeasureFolders=new Set();
let measureDocs=[],measureLoaded=false,measureLoadError='',measureFolder='all',measureDocId='',measureRowId='',measurePage=1,measureZoom=1,measureTool='point',measureColor='#e53935',measurePdf=null,measurePdfId='',measureLoadTask=null,measureRenderTask=null,measurePaintToken=0,measureBusy=false,measureDBPromise,measureSaveQueue=Promise.resolve(),measureSaveFailed=false;
const measurementRows=()=>measureDocs.filter(d=>d.projectId===projectId).reduce((n,d)=>n+d.rows.length,0);
function measureFolders(){data.measureFolders ||= [];data.measureFolderSetup ||= [];if(projectId&&!data.measureFolderSetup.includes(projectId)){for(const kind of Object.keys(MEASURE_KINDS))if(!data.measureFolders.some(f=>f.projectId===projectId&&f.defaultKind===kind))data.measureFolders.push({id:uid(),projectId,name:kind,kind,defaultKind:kind,parentId:''});data.measureFolderSetup.push(projectId);save();}return data.measureFolders.filter(f=>f.projectId===projectId);}
function measureCurrent(){return measureDocs.find(d=>d.id===measureDocId&&d.projectId===projectId);}
function measureCurrentRow(){return measureAllRows().find(r=>r.id===measureRowId);}

function measureAllRows(){return measureDocs.filter(d=>d.projectId===projectId).flatMap(d=>d.rows||[]);}
function measureRecordOwner(id=measureRowId){return measureDocs.find(d=>d.projectId===projectId&&(d.rows||[]).some(r=>r.id===id));}
function measureRowNumber(row){return row?.number||measureAllRows().findIndex(r=>r.id===row?.id)+1;}
function measureFolderRows(){const ids=new Set(measureVisibleDocs().flatMap(d=>(d.rows||[]).map(r=>r.id)));return measureAllRows().filter(r=>ids.has(r.id)).sort((a,b)=>measureRowNumber(a)-measureRowNumber(b));}
function nextMeasureNumber(){return measureDocs.filter(d=>d.projectId===projectId).reduce((max,d)=>Math.max(max,d.lastNumber||0,...(d.rows||[]).map(r=>r.number||0)),0)+1;}
function numberMeasureRecords(docs){const changed=[];for(const site of new Set(docs.map(d=>d.projectId))){const scoped=docs.filter(d=>d.projectId===site),used=new Set();let next=scoped.reduce((n,d)=>Math.max(n,d.lastNumber||0,...(d.rows||[]).map(r=>Number.isSafeInteger(r.number)?r.number:0)),0);for(const doc of scoped){let dirty=false;for(const row of doc.rows||[]){if(!Number.isSafeInteger(row.number)||row.number<1||used.has(row.number)){row.number=++next;dirty=true;}used.add(row.number);}const last=Math.max(doc.lastNumber||0,...(doc.rows||[]).map(r=>r.number));if(doc.lastNumber!==last){doc.lastNumber=last;dirty=true;}if(dirty)changed.push(doc);}}return changed;}
function createStandaloneMeasure(){const folderId=measureFolders().some(f=>f.id===measureFolder)?measureFolder:'';let owner=measureDocs.find(d=>d.projectId===projectId&&d.folderId===folderId&&d.type==='records');if(!owner){owner={id:uid(),projectId,folderId,type:'records',name:'実測記録',rows:[],marks:[],lastNumber:0};measureDocs.push(owner);}newMeasureRow(owner);measureDocId='';persistMeasure(owner);return owner;}
async function deleteMeasureRecord(id){if(measureFolderBusy)return;const owner=measureRecordOwner(id);if(!owner)return;measureFolderBusy=true;try{const changes=measureDocs.filter(d=>d.projectId===projectId&&(d===owner||d.marks.some(m=>m.rowId===id))).map(d=>({...d,rows:d.rows.filter(r=>r.id!==id),marks:d.marks.filter(m=>m.rowId!==id)}));await measureSaveQueue;await measureStoreBatch(changes);for(const changed of changes){const doc=measureDocs.find(d=>d.id===changed.id);doc.rows=changed.rows;doc.marks=changed.marks;}measureRowId='';}finally{measureFolderBusy=false;}}
async function removeMeasurePDF(doc){if(measureFolderBusy)return;measureFolderBusy=true;try{await measureSaveQueue;const retained={...doc,type:'records',name:'実測記録',marks:[]};delete retained.file;await measureStoreBatch([retained]);Object.keys(doc).forEach(key=>delete doc[key]);Object.assign(doc,retained);if(measureDocId===doc.id){measureDocId='';await disposeMeasurePdf();}}finally{measureFolderBusy=false;}}

function openMeasureDB(){return measureDBPromise ||= new Promise((resolve,reject)=>{const req=indexedDB.open('sekokan-measurements',1);req.onupgradeneeded=()=>req.result.createObjectStore('drawings',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>{measureDBPromise=null;reject(req.error)};});}
async function measureStore(mode,value){const db=await openMeasureDB();return new Promise((resolve,reject)=>{const tx=db.transaction('drawings',mode==='read'?'readonly':'readwrite'),store=tx.objectStore('drawings');let result;const req=mode==='read'?store.getAll():mode==='delete'?store.delete(value):store.put(value);req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('保存できません'));});}
function loadMeasurements(){if(measureLoaded)return;measureLoaded=true;measureStore('read').then(async rows=>{measureDocs=rows;const changed=numberMeasureRecords(rows);if(changed.length)await measureStoreBatch(changed);measureReady=true;if(page==='measurements'||page==='dashboard')render();}).catch(()=>{measureLoadError='保存した実測データを読み込めませんでした。再読み込みしてください。';if(page==='measurements')render();});}
function measureStatus(text,error=false){const el=document.querySelector('#measureStatus');if(el){el.textContent=text;el.classList.toggle('measure-error',error);}}
function persistMeasure(doc){const snapshot=structuredClone(doc);measureStatus('保存中…');measureSaveQueue=measureSaveQueue.catch(()=>{}).then(()=>measureStore('write',snapshot)).then(()=>{measureSaveFailed=false;measureStatus('保存しました');}).catch(error=>{measureSaveFailed=true;measureStatus('保存できませんでした。「再保存」を押してください。端末の空き容量も確認してください。',true);console.error(error);});return measureSaveQueue;}
function measureField(name,label,value='',type='text'){return `<label class="field">${esc(label)}<input name="${esc(name)}" type="${type}" ${type==='number'?'step="any" inputmode="decimal"':''} maxlength="160" value="${esc(value)}"></label>`;}

function measureBoltLayout(row){const count=n=>Math.max(2,Math.min(20,Math.trunc(Number(n))||2));return {...row.boltLayout,shape:'rectangle',columns:count(row.boltLayout?.columns),rows:count(row.boltLayout?.rows)};}
function measureBoltPoints(layout){const points=[],add=(x,y,edge)=>points.push({x,y,edge,number:points.length+1});for(let i=0;i<layout.columns;i++)add(70+180*i/(layout.columns-1),70,'top');for(let i=1;i<layout.rows;i++)add(250,70+180*i/(layout.rows-1),'right');for(let i=layout.columns-2;i>=0;i--)add(70+180*i/(layout.columns-1),250,'bottom');for(let i=layout.rows-2;i>0;i--)add(70,70+180*i/(layout.rows-1),'left');return points;}


let measureSelectedBoltRow='',measureSelectedBolt=1;
function measureBoltKey(row){const layout=measureBoltLayout(row);return layout.columns+'x'+layout.rows;}
function measureBoltValues(row,number){return row.boltMeasurements?.[measureBoltKey(row)]?.[number]||{x:'',y:''};}
function setMeasureBoltValue(row,number,axis,value){if(!['x','y'].includes(axis)||!measureBoltPoints(measureBoltLayout(row)).some(p=>p.number===number))return;row.boltMeasurements ||= {};const key=measureBoltKey(row);row.boltMeasurements[key] ||= {};row.boltMeasurements[key][number] ||= {x:'',y:''};row.boltMeasurements[key][number][axis]=value;}
function renderMeasureBoltTable(row){const points=measureBoltPoints(measureBoltLayout(row));return `<div class="measure-bolt-results"><h4>ボルト別のX・Yずれ（mm）</h4><p class="hint">左上から時計回りに番号を振ります。図の向きで＋Xは右、＋Yは上。設計位置からのずれを入力します。「±」で正負を切り替えられます。</p><div class="measure-bolt-table" role="table" aria-label="ボルト別の実測値"><div class="measure-bolt-table-head" role="row"><b role="columnheader">ボルト番号</b><b role="columnheader">Xずれ（mm）</b><b role="columnheader">Yずれ（mm）</b></div>${points.map(p=>{const values=measureBoltValues(row,p.number);return `<div class="measure-bolt-input-row" role="row" data-bolt-input-row="${p.number}"><button type="button" class="btn secondary" data-bolt-select="${p.number}" aria-label="ボルト${p.number}を選択">No.${p.number}</button>${['x','y'].map(axis=>`<div class="measure-bolt-signed" role="cell"><input type="text" inputmode="decimal" maxlength="20" data-measure-bolt-number="${p.number}" data-measure-bolt-axis="${axis}" value="${esc(values[axis])}" aria-label="ボルト${p.number}の${axis.toUpperCase()}ずれ（mm）" placeholder="未測定"><button type="button" data-bolt-sign-number="${p.number}" data-bolt-sign-axis="${axis}" aria-label="ボルト${p.number}の${axis.toUpperCase()}ずれの正負を切替">±</button></div>`).join('')}</div>`;}).join('')}</div><p class="hint">本数を変更した場合は、配置ごとに実測値を保存します。元の本数に戻すと以前の値を復元します。</p>${row.values?.some(v=>['位置ずれ X','位置ずれ Y'].includes(v.label))?'<p class="hint">従来の「位置ずれX・Y」は共通項目として下に残しています。1本ごとのずれはこの欄に記入してください。</p>':''}</div>`;}
function selectMeasureBolt(number,focus=true){const row=measureCurrentRow();if(!row||!measureBoltPoints(measureBoltLayout(row)).some(p=>p.number===number))return;measureSelectedBoltRow=row.id;measureSelectedBolt=number;refreshMeasureBoltDiagram(row);document.querySelectorAll('[data-bolt-input-row]').forEach(el=>el.classList.toggle('selected',Number(el.dataset.boltInputRow)===number));if(focus){const input=document.querySelector(`[data-measure-bolt-number="${number}"][data-measure-bolt-axis="x"]`);input?.scrollIntoView({block:'nearest',behavior:'smooth'});input?.focus({preventScroll:true});}}

function measurePlateGeometry(row){const layout=measureBoltLayout(row),valid=n=>Number.isFinite(Number(n))&&Number(n)>0&&Number(n)<=100000,width=Number(layout.plateWidth),height=Number(layout.plateHeight),specified=valid(layout.plateWidth)&&valid(layout.plateHeight),w=specified?240*width/Math.max(width,height):240,h=specified?240*height/Math.max(width,height):240;return {w,h,x:160-w/2,y:160-h/2,specified};}
function renderMeasureBoltDiagram(row){const layout=measureBoltLayout(row),g=measurePlateGeometry(row),points=measureBoltPoints(layout).map(p=>({...p,x:g.x+(p.x-40)/240*g.w,y:g.y+(p.y-40)/240*g.h}));const gap=Math.min(g.w*.75/(layout.columns-1),g.h*.75/(layout.rows-1)),font=Math.max(5,Math.min(11,gap*.65)),radius=Math.max(1,Math.min(5,gap/4));return `<svg style="min-width:${Math.max(320,Math.ceil(320*11/font))}px" class="measure-bolt-diagram" viewBox="0 0 320 320" role="img" aria-label="符号${esc(row.code||'未入力')}、ベースプレート${g.specified?esc(layout.plateWidth)+'×'+esc(layout.plateHeight)+'mm':'寸法未設定'}、合計${points.length}本"><text x="160" y="18" text-anchor="middle" font-size="14" fill="#334155">${esc(row.code||'符号未入力')}</text><rect x="${g.x}" y="${g.y}" width="${g.w}" height="${g.h}" fill="#f1f5f9" stroke="#334155" stroke-width="2"/><rect x="${g.x+g.w/24}" y="${g.y+g.h/24}" width="${g.w*22/24}" height="${g.h*22/24}" fill="white" stroke="#64748b"/><path d="M160 25V290M25 160H290" stroke="#94a3b8" stroke-dasharray="12 4 2 4"/><rect x="${160-g.w/6}" y="${160-g.h/6}" width="${g.w/3}" height="${g.h/3}" fill="#e2e8f0" stroke="#334155" stroke-width="3"/><text x="160" y="165" text-anchor="middle" font-size="14" fill="#334155">柱</text>${points.map(p=>{const selected=measureSelectedBoltRow===row.id&&measureSelectedBolt===p.number,tx=p.edge==='right'?p.x+11:p.edge==='left'?p.x-11:p.x,ty=p.edge==='top'?p.y-12:p.edge==='bottom'?p.y+19:p.y+font/3,anchor=p.edge==='right'?'start':p.edge==='left'?'end':'middle';return `<g class="measure-bolt-point" data-bolt-select="${p.number}" role="button" tabindex="0" aria-label="ボルト${p.number}の実測欄を開く"><circle cx="${p.x}" cy="${p.y}" r="${radius+3}" fill="transparent"/><circle cx="${p.x}" cy="${p.y}" r="${radius}" fill="${selected?'#f59e0b':'white'}" stroke="#2563eb" stroke-width="2"/><path d="M${p.x-radius-2} ${p.y}h${2*(radius+2)}M${p.x} ${p.y-radius-2}v${2*(radius+2)}" stroke="#2563eb"/><text x="${tx}" y="${ty}" text-anchor="${anchor}" font-size="${font}" font-weight="bold" fill="#1e40af">${p.number}</text></g>`;}).join('')}<text x="160" y="310" text-anchor="middle" font-size="13" fill="#334155">横：${g.specified?esc(layout.plateWidth)+' mm':'未設定'}</text><text x="14" y="160" transform="rotate(-90 14 160)" text-anchor="middle" font-size="13" fill="#334155">縦：${g.specified?esc(layout.plateHeight)+' mm':'未設定'}</text></svg>`;}
function refreshMeasureBoltDiagram(row){const svg=document.querySelector('.measure-bolt-diagram');if(svg)svg.outerHTML=renderMeasureBoltDiagram(row);}

function renderMeasureBoltLayout(row){if(row.kind!=='鉄骨')return '';const layout=measureBoltLayout(row),points=measureBoltPoints(layout);return `<section class="measure-bolt-layout"><h3>アンカーボルト配置図</h3><div class="measure-plate-fields">${[['plateWidth','プレート横寸法（mm）'],['plateHeight','プレート縦寸法（mm）']].map(([key,label])=>`<label class="field">${label}<input type="number" min="0.1" max="100000" step="any" inputmode="decimal" data-plate-dimension="${key}" value="${esc(layout[key]||'')}" placeholder="例：600"></label>`).join('')}</div><div class="measure-bolt-controls">${[['columns','横方向（各辺）'],['rows','縦方向（各辺）']].map(([axis,label])=>`<div><span>${label}</span><div class="measure-bolt-stepper"><button type="button" class="btn secondary" data-bolt-axis="${axis}" data-bolt-step="-1" aria-label="${label}を1本減らす" ${layout[axis]<=2?'disabled':''}>−</button><b>${layout[axis]}本</b><button type="button" class="btn secondary" data-bolt-axis="${axis}" data-bolt-step="1" aria-label="${label}を1本増やす" ${layout[axis]>=20?'disabled':''}>＋</button></div></div>`).join('')}</div><div class="measure-bolt-preview">${renderMeasureBoltDiagram(row)}</div><p class="measure-bolt-total">合計 ${points.length}本</p><p class="hint">四隅は重複せず数えます。各辺2〜20本。横・縦の寸法を指定するとプレートの縦横比が変わります。ボルトは等間隔の配置イメージで、ピッチや柱寸法・印刷縮尺を表しません。円形・設計図からの自動読取りは未対応です。</p>${renderMeasureBoltTable(row)}</section>`;}
document.addEventListener('click',e=>{if(measureFolderBusy)return;const b=e.target.closest('[data-bolt-axis]');if(!b)return;const row=measureCurrentRow(),doc=measureRecordOwner();if(!row||!doc||row.kind!=='鉄骨')return;const axis=b.dataset.boltAxis;if(!['columns','rows'].includes(axis))return;const layout=measureBoltLayout(row);layout[axis]=Math.max(2,Math.min(20,layout[axis]+Number(b.dataset.boltStep)));row.boltLayout=layout;measureSelectedBoltRow='';measureSelectedBolt=1;persistMeasure(doc);const panel=b.closest('.measure-bolt-layout');if(panel){panel.outerHTML=renderMeasureBoltLayout(row);document.querySelector(`[data-bolt-axis="${axis}"][data-bolt-step="${b.dataset.boltStep}"]`)?.focus();}});

function renderMeasureRecordList(){const rows=measureFolderRows();return `<section class="measure-folder-records"><div class="section-head"><h2>実測記録</h2><button type="button" class="btn secondary" data-measure-item-move="row" ${measureCurrentRow()?'':'disabled'}>選択した実測を移動</button></div><div class="measure-record-list">${rows.map(r=>`<button class="measure-record-button ${r.id===measureRowId?'selected':''}" data-measure-row="${esc(r.id)}" draggable="true" data-measure-drag-kind="row" data-measure-drag-id="${esc(r.id)}"><b>${measureRowNumber(r)}</b><span>${r.code?esc(r.code)+' · ':''}${esc(r.title||'名称未入力')}<small>${esc(r.location||'場所未入力')} · ${esc(r.kind)} · ${measureDocs.filter(d=>d.projectId===projectId&&d.type!=='records').some(d=>d.marks.some(m=>m.rowId===r.id))?'PDF配置済み':'PDF未配置'}</small></span></button>`).join('')||'<p class="hint">「新規実測」で番号付きの記録を追加できます。</p>'}</div><p class="hint measure-move-hint">実測記録・PDFを左のフォルダーやフォルダーカードへドラッグして移動できます。スマホでは「移動」ボタンを使えます。</p></section>`;}
function renderMeasureFolderActions(){const active=measureFolders().some(f=>f.id===measureFolder);return `<div class="measure-top-actions"><button type="button" class="btn" data-measure-new ${measureReady&&!measureBusy&&!measureFolderBusy?'':'disabled'}>＋ 新規実測</button><label class="btn measure-upload ${measureBusy?'measure-disabled':''}">${measureBusy?'読込中…':'＋ PDF図面を追加'}<input id="measurePdfFile" type="file" accept="application/pdf,.pdf" ${measureBusy?'disabled':''}></label>${active?'<button type="button" class="btn secondary" data-measure-folder-rename>名前を変更</button><button type="button" class="btn secondary" data-measure-folder-move>フォルダー移動</button><button type="button" class="btn danger" data-measure-folder-delete>フォルダー消去</button>':''}</div>`;}
function renderMeasureDrawing(doc){return `${doc?`<section class="card measure-drawing"><div class="measure-toolbar"><button class="btn secondary" data-measure-prev ${measurePage<=1?'disabled':''}>前</button><span id="measurePageInfo">${measurePage}ページ</span><button class="btn secondary" data-measure-next>次</button><label>拡大<select id="measureZoom"><option value="1">100%</option><option value="1.5">150%</option><option value="2">200%</option><option value="3">300%</option></select></label><label>操作<select id="measureTool">${[['point','番号・測点'],['line','線'],['rect','囲み'],['highlight','マーカー'],['pan','移動・スクロール']].map(([v,t])=>`<option value="${v}" ${measureTool===v?'selected':''}>${t}</option>`).join('')}</select></label><label>色<input id="measureColor" type="color" value="${measureColor}"></label><button class="btn secondary" data-measure-undo ${doc.marks.some(m=>m.page===measurePage)?'':'disabled'}>直前の印を戻す</button></div><p class="hint">図面をタップすると、既存の実測番号を配置するか、新規実測を作成するか選べます。線・囲み・マーカーはドラッグ後に選択します。左側の実測番号を図面上へドラッグして配置することもできます。配置済みの番号を押すと実測欄が開きます。</p><div class="measure-scroll"><div class="measure-canvas-wrap"><canvas id="measureCanvas" aria-label="実測用PDF図面"></canvas><svg id="measureOverlay" xmlns="http://www.w3.org/2000/svg" aria-label="図面の色付きマーキング"></svg></div></div></section>`:'<section class="card measure-drawing measure-no-pdf"><h2>PDFなしで実測を作成できます</h2><p>新規実測で鉄骨情報を入力し、後からPDFを追加してください。既存の番号付き記録を選択し、図面をタップして配置できます。</p></section>'}`;}
function renderMeasureDetails(doc){const row=measureCurrentRow();return `<section class="card measure-records"><div class="section-head"><h2>実測内容</h2></div>${row?`<form id="measureRecordForm"><h3 class="measure-record-number">実測 No.${measureRowNumber(row)}</h3>${doc?`<button type="button" class="btn secondary" data-measure-place>No.${measureRowNumber(row)}をこのPDFに配置</button>`:'<p class="hint">PDFを追加・選択すると、この番号を図面に配置できます。</p>'}<label class="field">分類<select name="kind">${Object.keys(MEASURE_KINDS).map(k=>`<option ${row.kind===k?'selected':''}>${k}</option>`).join('')}</select></label>${measureField('title','実測するもの',row.title)}${measureField('code','符号（例：C1・BP1）',row.code||'')}${measureField('location','場所・通り芯・階',row.location)}${measureField('date','実測日',row.date,'date')}${renderMeasureBoltLayout(row)}<p class="hint">単位は項目ごとに記入できます。許容差の自動判定は行いません。</p><div class="measure-values"><div class="measure-value-head"><b>項目</b><b>設計値</b><b>実測値</b><b>単位</b></div>${row.values.map((v,i)=>`<div class="measure-value-row"><input aria-label="項目${i+1}" data-measure-value="${i}:label" value="${esc(v.label)}" maxlength="80"><input aria-label="設計値${i+1}" data-measure-value="${i}:design" value="${esc(v.design)}" inputmode="decimal" maxlength="80"><input aria-label="実測値${i+1}" data-measure-value="${i}:actual" value="${esc(v.actual)}" inputmode="decimal" maxlength="80"><input aria-label="単位${i+1}" data-measure-value="${i}:unit" value="${esc(v.unit)}" maxlength="20"></div>`).join('')}</div><button type="button" class="btn secondary" data-measure-value-add>＋ 測定項目</button><label class="field">備考<textarea name="note" maxlength="1000">${esc(row.note)}</textarea></label><div class="measure-actions"><button class="btn" type="submit">保存</button><button class="btn danger" type="button" data-measure-row-delete>この記録を削除</button></div></form>`:'<p class="hint">番号付きの記録を選ぶと、設計値と実測値を記入できます。</p>'}</section>`;}
function renderMeasureEditor(doc){return `<div class="measure-workspace">${renderMeasureDetails(doc)}${renderMeasureDrawing(doc)}</div>`;}

function measureInFolder(id,selected){const folders=measureFolders(),seen=new Set();while(id&&!seen.has(id)){if(id===selected)return true;seen.add(id);id=folders.find(f=>f.id===id)?.parentId;}return false;}
function measureVisibleDocs(){return measureDocs.filter(d=>d.projectId===projectId&&(measureFolder==='all'||(measureFolder==='none'?!d.folderId:measureInFolder(d.folderId,measureFolder))));}
function measureFolderCount(id){return measureDocs.filter(d=>d.projectId===projectId&&(id==='all'||(id==='none'?!d.folderId:measureInFolder(d.folderId,id)))).reduce((n,d)=>n+d.rows.length,0);}
function measureFolderPDFCount(id){return measureDocs.filter(d=>d.projectId===projectId&&d.type!=='records'&&(id==='all'||(id==='none'?!d.folderId:measureInFolder(d.folderId,id)))).length;}
function measureSortedFolders(list){const all=measureFolders();return list.slice().sort((a,b)=>(Number.isFinite(a.order)?a.order:all.indexOf(a))-(Number.isFinite(b.order)?b.order:all.indexOf(b)));}
function measureFolderDragAttributes(id){return ['all','none'].includes(id)?'':`draggable="true" data-drag-folder="measure:${esc(id)}" title="ドラッグ：上・下で並べ替え、中央でフォルダー内へ移動"`;}
