let measurePendingPlacement=null;
function measurePlacementRows(){const doc=measureDocs.find(d=>d.id===(measurePendingPlacement?.docId||measureDocId)&&d.projectId===projectId&&d.type!=='records');return doc?measureDirectRows(doc.folderId||'none'):[];}
function renderMeasurePlacementChoice(){const rows=measurePlacementRows();return `<h2 id="measurePlacementTitle">PDFに配置する実測を選択</h2><p>このPDFと同じフォルダーの実測番号を使うか、新しく実測記録を作成するか選んでください。</p><section><h3>既存の実測番号を配置</h3><label for="measurePlacementRow">実測番号</label><select id="measurePlacementRow" ${rows.length?'':'disabled'}>${rows.map(r=>`<option value="${esc(r.id)}" ${r.id===measureRowId?'selected':''}>No.${measureRowNumber(r)} · ${esc(r.code||'')} ${esc(r.title||'名称未入力')}</option>`).join('')||'<option>このフォルダーに実測記録がありません</option>'}</select><button type="button" class="btn" data-measure-placement-existing ${rows.length?'':'disabled'}>この番号を配置</button></section><section><h3>新規実測を作成</h3><p>新しい番号を発行し、配置後に実測情報を入力します。</p><button type="button" class="btn secondary" data-measure-placement-new>＋ 新規実測を作成して配置</button></section><div class="measure-actions"><button type="button" class="btn secondary" data-measure-placement-cancel>キャンセル</button></div>`;}
function closeMeasurePlacementChoice(){const dialog=document.querySelector('#measurePlacementDialog');measurePendingPlacement=null;if(dialog){dialog.close();dialog.remove();}drawMeasureMarks();}
function openMeasurePlacementChoice(doc,mark){
 if(measureBusy||measureFolderBusy||!measureReady)return;
 closeMeasurePlacementChoice();measurePendingPlacement={docId:doc.id,site:projectId,mark};
 const dialog=document.createElement('dialog');dialog.id='measurePlacementDialog';dialog.className='measure-placement-dialog';dialog.setAttribute('aria-labelledby','measurePlacementTitle');dialog.innerHTML=renderMeasurePlacementChoice();
 dialog.addEventListener('cancel',e=>{e.preventDefault();closeMeasurePlacementChoice();});
 document.body.appendChild(dialog);dialog.showModal();
}
function commitMeasurePlacement(mode,rowId=''){
 const pending=measurePendingPlacement;if(!pending||measureBusy||measureFolderBusy||pending.site!==projectId||page!=='measurements')return false;
 const doc=measureDocs.find(d=>d.id===pending.docId&&d.projectId===pending.site&&d.type!=='records');if(!doc)return false;
 let row;if(mode==='existing')row=measurePlacementRows().find(r=>r.id===rowId);else if(mode==='new')row=newMeasureRow(doc);else return false;
 if(!row)return false;
 measureRowId=row.id;doc.marks.push({id:uid(),...pending.mark,rowId:row.id});persistMeasure(doc);closeMeasurePlacementChoice();render();return true;
}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-measure-placement-existing],[data-measure-placement-new],[data-measure-placement-cancel],[data-measure-sidebar-row]');if(!b||measureBusy||measureFolderBusy)return;
 if(b.hasAttribute('data-measure-placement-cancel')){closeMeasurePlacementChoice();return;}
 if(b.hasAttribute('data-measure-placement-existing')){commitMeasurePlacement('existing',document.querySelector('#measurePlacementRow')?.value);return;}
 if(b.hasAttribute('data-measure-placement-new')){commitMeasurePlacement('new');return;}
 const row=measureAllRows().find(r=>r.id===b.dataset.measureSidebarRow);if(!row)return;
 measureFolder=b.dataset.measureRecordFolder;collapsedMeasureFolders.delete(measureFolder);measureDocId='';measureRowId=row.id;measurePage=1;render();
 document.querySelector('#measureRecordForm')?.scrollIntoView({block:'start',behavior:'smooth'});
});

// Move records independently of PDF placement, keeping IDs and fixed numbers intact.
let measureDragSource=null;
async function moveMeasureItem(kind,id,target,site=projectId){
 if(!measureReady||measureBusy||measureFolderBusy||site!==projectId)return false;
 const folderId=target==='none'?'':target;
 if(target==='all'||(folderId&&!data.measureFolders.some(f=>f.projectId===site&&f.id===folderId)))return false;
 if(!['row','pdf'].includes(kind))return false;
 measureFolderBusy=true;
 try{
  await measureSaveQueue;
  if(measureSaveFailed)throw Error('未保存の変更があります。先に再保存してください。');
  const owner=measureDocs.find(d=>d.projectId===site&&(kind==='row'?(d.rows||[]).some(r=>r.id===id):d.id===id&&d.type!=='records'));
  if(!owner||owner.folderId===folderId)return false;
  let updates;
  if(kind==='pdf')updates=[{...owner,folderId}];
  else{
   const row=owner.rows.find(r=>r.id===id);
   const destination=measureDocs.find(d=>d.projectId===site&&d.type==='records'&&(d.folderId||'')===folderId)||{id:uid(),projectId:site,folderId,type:'records',name:'実測記録',rows:[],marks:[],lastNumber:0};
   updates=[{...owner,rows:owner.rows.filter(r=>r.id!==id)},{...destination,rows:[...destination.rows,row],lastNumber:Math.max(destination.lastNumber||0,row.number||0)}];
  }
  await measureStoreBatch(updates);
  for(const update of updates){const existing=measureDocs.find(d=>d.id===update.id);if(existing)Object.assign(existing,update);else measureDocs.push(update);}
  // PDF marks continue to reference the same row ID even across folders.
  if(projectId===site){if(kind==='row'&&measureRowId===id)measureRowId='';if(kind==='pdf'&&measureDocId===id){measureDocId='';measureRowId='';await disposeMeasurePdf();}}
  return true;
 }catch(error){alert('移動できませんでした。'+(error.message||'端末の空き容量と保存状態を確認してください。'));return false;}
 finally{measureFolderBusy=false;render();}
}
function clearMeasureDrag(){measureDragSource=null;document.querySelectorAll('.measure-drop-active,.measure-item-dragging').forEach(el=>el.classList.remove('measure-drop-active','measure-item-dragging'));}
document.addEventListener('dragstart',e=>{
 const el=e.target.closest?.('[data-measure-drag-kind]');if(!el||page!=='measurements')return;
 if(measureBusy||measureFolderBusy||!measureReady){e.preventDefault();return;}
 measureDragSource={kind:el.dataset.measureDragKind,id:el.dataset.measureDragId,site:projectId};
 e.dataTransfer.effectAllowed=measureDragSource.kind==='row'?'all':'move';e.dataTransfer.setData('application/x-sekokan-measurement',JSON.stringify(measureDragSource));e.dataTransfer.setData('text/plain',el.textContent);el.classList.add('measure-item-dragging');
});
document.addEventListener('dragover',e=>{
 const el=e.target.closest?.('[data-measure-drop-folder]');if(!el||!measureDragSource||measureDragSource.site!==projectId||el.dataset.measureDropFolder==='all')return;
 e.preventDefault();e.dataTransfer.dropEffect='move';document.querySelectorAll('.measure-drop-active').forEach(node=>node.classList.remove('measure-drop-active'));el.classList.add('measure-drop-active');
});
document.addEventListener('dragleave',e=>{const el=e.target.closest?.('[data-measure-drop-folder]');if(el&&!el.contains(e.relatedTarget))el.classList.remove('measure-drop-active');});
document.addEventListener('drop',async e=>{
 const el=e.target.closest?.('[data-measure-drop-folder]'),source=measureDragSource;if(!el||!source||el.dataset.measureDropFolder==='all')return;
 e.preventDefault();const target=el.dataset.measureDropFolder;clearMeasureDrag();await moveMeasureItem(source.kind,source.id,target,source.site);
});
document.addEventListener('dragend',clearMeasureDrag);
// Dropping a numbered record on the drawing adds a placement, not a new record or a folder move.
function placeDraggedMeasure(source,doc,point){
 if(page!=='measurements'||!measureReady||measureBusy||measureFolderBusy||source?.site!==projectId||source.kind!=='row'||!doc||doc.projectId!==projectId||doc.type==='records')return false;
 const row=measureAllRows().find(r=>r.id===source.id);if(!row)return false;
 doc.marks.push({id:uid(),x:point.x,y:point.y,x2:point.x,y2:point.y,tool:'point',color:measureColor,page:measurePage,rowId:row.id});
 measureRowId=row.id;persistMeasure(doc);drawMeasureMarks();return true;
}
document.addEventListener('dragover',e=>{
 const overlay=e.target.closest?.('#measureOverlay');if(!overlay||measureDragSource?.kind!=='row'||measureDragSource.site!==projectId||measureBusy||measureFolderBusy)return;
 e.preventDefault();e.dataTransfer.dropEffect='link';overlay.classList.add('measure-pdf-drop-active');
});
document.addEventListener('dragleave',e=>{const overlay=e.target.closest?.('#measureOverlay');if(overlay&&!overlay.contains(e.relatedTarget))overlay.classList.remove('measure-pdf-drop-active');});
document.addEventListener('drop',e=>{
 const overlay=e.target.closest?.('#measureOverlay'),source=measureDragSource;if(!overlay||source?.kind!=='row')return;
 e.preventDefault();const doc=measureCurrent(),point=measurePoint(e,overlay);overlay.classList.remove('measure-pdf-drop-active');clearMeasureDrag();
 if(placeDraggedMeasure(source,doc,point)){
  // Refresh the selected record without reloading the PDF or losing its scroll position.
  document.querySelectorAll('[data-measure-row],[data-measure-sidebar-row]').forEach(el=>el.classList.toggle('selected',(el.dataset.measureRow||el.dataset.measureSidebarRow)===source.id));
  const details=document.querySelector('.measure-records');if(details)details.outerHTML=renderMeasureDetails(doc);else document.querySelector('.measure-folder-records')?.insertAdjacentHTML('afterend',renderMeasureDetails(doc));
  const move=document.querySelector('[data-measure-item-move="row"]');if(move)move.disabled=false;
  measureStatus('No.'+measureRowNumber(measureCurrentRow())+' をPDFに配置しました。実測記録は元のフォルダーに残ります。');
 }
});
document.addEventListener('dragend',()=>document.querySelectorAll('.measure-pdf-drop-active').forEach(el=>el.classList.remove('measure-pdf-drop-active')));
document.addEventListener('click',async e=>{
 const button=e.target.closest('[data-measure-item-move]');if(!button||measureBusy||measureFolderBusy)return;
 const kind=button.dataset.measureItemMove,id=kind==='row'?measureCurrentRow()?.id:measureCurrent()?.id;if(!id)return;
 const choices=[{id:'none',name:'未分類'},...measureFolders()];
 const answer=prompt('移動先の番号を入力してください\n'+choices.map((f,i)=>`${i}：${f.name}`).join('\n'));
 if(answer===null||!/^\d+$/.test(answer.trim())||!choices[Number(answer)])return;
 await moveMeasureItem(kind,id,choices[Number(answer)].id);
});
